export const SETTING = "Kestrel Valley District (fictional, population 600,000) has a high burden of [[b|tuberculosis]] (TB). Its TB programme must decide which strategy to fund from 2027 to bring TB down by 2035. You have joined the programme as its AI lead.";

export const LLM_EVIDENCE = ["Extraction checked", "Curve fitted", "Code reviewed"];
export const VDB_EVIDENCE = ["Metric compared", "Filtered search", "Analogues vetted"];
